// =========================================================================
// Arvento oturum yonetimi - TEK OTURUM KISITI yuzunden cache ZORUNLU.
// =========================================================================
// 2026-09-14 canli test: her POST /v1/login yeni sessionId uretiyor ve
// ONCEKINI ANINDA OLDURUYOR (eski sid -> HTTP 401, bos body). Bu workflow
// mesai icinde dakikada bir calisiyor; her calistirmada login atsaydi
// sistem kendi oturumunu surekli kesecekti. Panorama'nin Login node'u
// cache'lemiyor ama o gunde 21 kez calisiyor - bizde ~800.
//
// Ayni sebeple konum ve filo/bakim isleri AYRI workflow degil: ikisi de bu
// dugumu ve ayni static data cache'ini paylasmak zorunda.
//
// TTL neden 30 dk: sessionId'nin gercek omru Arvento'ya soruldu, cevap
// gelmedi (sunucu tarafi ayari, API yanitinda yok). 30 dk muhafazakar bir
// tahmin. Erken duserse asagidaki 401 dali zaten yakalar; gec duserse
// yalnizca gereksiz bir login olur. Arvento cevap verince tek sabit degisir.
//
// Static data yalniz AKTIF workflow'da kalicidir; import/guncelleme sonrasi
// sifirlanir - o durumu da 401 dali toplar.
// =========================================================================

const TTL_MS = 30 * 60 * 1000;

const sd = $getWorkflowStaticData('global');
const items = $input.all();
const isTuru = (items[0] && items[0].json && items[0].json.is_turu) || 'konum';

const cacheGecerli =
  typeof sd.arventoSid === 'string' &&
  sd.arventoSid.length > 0 &&
  typeof sd.arventoSidExpiry === 'number' &&
  Date.now() < sd.arventoSidExpiry;

if (cacheGecerli) {
  return [{ json: { sid: sd.arventoSid, is_turu: isTuru, oturum_kaynagi: 'cache' } }];
}

const userName = $env.ARVENTO_USER;
const password = $env.ARVENTO_PASS;
if (!userName || !password) {
  throw new Error(
    'ARVENTO_USER / ARVENTO_PASS ortam degiskenleri tanimli degil. ' +
    'n8n Settings > Environment Variables altindan girilmeli. ' +
    'Bu degerler workflow JSON dosyasina YAZILMAZ.'
  );
}

let res;
try {
  res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://ws.arvento.com/api/v1/login',
    headers: { 'Content-Type': 'application/json' },
    body: { UserName: userName, Password: password },
    json: true,
    timeout: 30000,
  });
} catch (e) {
  throw new Error('Arvento login istegi basarisiz: ' + (e && e.message ? e.message : e));
}

if (res && res.HasError === true) {
  const msg = (res.Error && res.Error.Message) || res.Message || '(mesaj yok)';
  throw new Error('Arvento login reddetti - Status=' + res.Status + ', Message=' + msg);
}

const sid = res && res.Record ? res.Record.sessionId : null;
if (!sid) {
  throw new Error('Arvento login yanitinda Record.sessionId yok: ' + JSON.stringify(res).slice(0, 300));
}

sd.arventoSid = sid;
sd.arventoSidExpiry = Date.now() + TTL_MS;
sd.arventoSidAlindi = new Date().toISOString();

return [{ json: { sid: sid, is_turu: isTuru, oturum_kaynagi: 'yeni-login' } }];

// =========================================================================
// Oturum tazeleme - yalniz lastEvents HTTP 401 dondugunde calisir.
// =========================================================================
// 401 su durumlarda gelir:
//   - TTL tahminimiz gercek omurden uzun kaldi,
//   - baska bir yerden (Postman, baska n8n ornegi, Arvento web arayuzu)
//     ayni hesapla login atildi ve bizim sid'imiz oldu (tek-oturum kisiti),
//   - workflow import/guncelleme sonrasi static data sifirlandi.
// Cache burada ONCE silinir ki basarisiz bir tazelemede bayat sid geri
// donmesin.
// =========================================================================

const sd = $getWorkflowStaticData('global');
delete sd.arventoSid;
delete sd.arventoSidExpiry;

const items = $input.all();
const isTuru = (items[0] && items[0].json && items[0].json.is_turu) || 'konum';

const userName = $env.ARVENTO_USER;
const password = $env.ARVENTO_PASS;
if (!userName || !password) {
  throw new Error(
    'ARVENTO_USER / ARVENTO_PASS ortam degiskenleri tanimli degil. ' +
    'n8n Settings > Environment Variables altindan girilmeli. ' +
    'Bu degerler workflow JSON dosyasina YAZILMAZ.'
  );
}

let res;
try {
  res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://ws.arvento.com/api/v1/login',
    headers: { 'Content-Type': 'application/json' },
    body: { UserName: userName, Password: password },
    json: true,
    timeout: 30000,
  });
} catch (e) {
  throw new Error('Arvento login istegi basarisiz: ' + (e && e.message ? e.message : e));
}

if (res && res.HasError === true) {
  const msg = (res.Error && res.Error.Message) || res.Message || '(mesaj yok)';
  throw new Error('Arvento login reddetti - Status=' + res.Status + ', Message=' + msg);
}

const sid = res && res.Record ? res.Record.sessionId : null;
if (!sid) {
  throw new Error('Arvento login yanitinda Record.sessionId yok: ' + JSON.stringify(res).slice(0, 300));
}

sd.arventoSid = sid;
sd.arventoSidExpiry = Date.now() + 30 * 60 * 1000;
sd.arventoSidAlindi = new Date().toISOString();

return [{ json: { sid: sid, is_turu: isTuru, oturum_kaynagi: 'tazelendi-401' } }];

// =========================================================================
// lastEvents yanitini dogrula + Supabase satirlarina cevir
// =========================================================================
// Dogrulama sirasi bilerek katmanli: google-places-prospecting'te
// 2026-09-14'te yasanan bug tam olarak "401 govdesi hata sayilmadan asagi
// akti" idi. neverError:true kullandigimiz icin HTTP katmani sessiz -
// kontrolu burada acikca yapiyoruz.
//
// Arvento sozlesmesi (2026-09-14 canli test):
//   - HTTP kodu her zaman 200; hata HasError/Status alanlarinda.
//     Tek istisna gecersiz sid -> gercek 401 + bos body.
//   - Status 0 = basarili, 1000 = null reference, 1012 = InvalidDateInterval.
//   - Date alani "20260914095947" = TURKIYE YEREL SAATI (UTC+3), UTC DEGIL.
//     HTTP date header 06:59:47 GMT iken API 09:59:47 dondu.
//   - Gecersiz node hata vermiyor, satiri sessizce listeden dusuruyor.
// =========================================================================

const TR_OFFSET = '+03:00';

function tarihCevir(ham) {
  const m = /^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})$/.exec(String(ham == null ? '' : ham).trim());
  if (!m) return null;
  const d = new Date(m[1] + '-' + m[2] + '-' + m[3] + 'T' + m[4] + ':' + m[5] + ':' + m[6] + TR_OFFSET);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function sayi(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function metin(v) {
  const s = String(v == null ? '' : v).trim();
  return s === '' ? null : s;
}

const items = $input.all();
if (items.length === 0) {
  throw new Error('lastEvents dugumunden hic item gelmedi.');
}

const res = items[0].json;
const status = res.statusCode;
const body = res.body !== undefined ? res.body : res;

if (status === 401) {
  throw new Error(
    'Arvento oturumu gecersiz (401) - yeniden login denemesi de basarisiz oldu. ' +
    'Tek-oturum kisiti: ayni hesapla baska bir yerden login atilmis olabilir.'
  );
}
if (typeof status === 'number' && (status < 200 || status >= 300)) {
  throw new Error('Arvento lastEvents HTTP ' + status + ': ' + JSON.stringify(body).slice(0, 400));
}
if (!body || typeof body !== 'object') {
  throw new Error('Arvento lastEvents govdesi nesne degil: ' + String(body).slice(0, 300));
}
if (body.HasError === true) {
  const msg = (body.Error && body.Error.Message) || body.Message || '(mesaj yok)';
  throw new Error('Arvento lastEvents hata dondu - Status=' + body.Status + ', Message=' + msg);
}
if (body.Status !== 0) {
  throw new Error('Arvento lastEvents beklenmeyen Status=' + body.Status + ' (0 bekleniyordu): ' + JSON.stringify(body).slice(0, 300));
}
if (!Array.isArray(body.List)) {
  throw new Error('Arvento lastEvents yanitinda List dizisi yok: ' + JSON.stringify(body).slice(0, 400));
}

const cekildiAt = new Date().toISOString();
const son = [];
const gecmis = [];
const atlanan = { koordinatsiz: 0, tarihsiz: 0, nodesuz: 0 };

for (const ham of body.List) {
  const node = metin(ham.Node);
  if (!node) { atlanan.nodesuz += 1; continue; }

  const olcum = tarihCevir(ham.Date);
  if (!olcum) { atlanan.tarihsiz += 1; continue; }

  const lat = sayi(ham.Latitude);
  const lon = sayi(ham.Longitude);
  // Koordinat filtresi: 0/null sahte konumdur, yazilmaz.
  // (Repo geneli kural - musteri geocode'unda da ayni filtre var.)
  if (lat === null || lon === null || lat === 0 || lon === 0) { atlanan.koordinatsiz += 1; continue; }

  const hizHam = sayi(ham.Speed);
  const hiz = hizHam === null ? null : Math.max(0, hizHam);
  const yonHam = sayi(ham.Course);
  const yon = yonHam === null ? null : ((yonHam % 360) + 360) % 360;
  const odo = sayi(ham.Odometer);

  son.push({
    node: node,
    olcum_zamani: olcum,
    ham_tarih: metin(ham.Date),
    lat: lat,
    lon: lon,
    hiz_kmh: hiz,
    yon_derece: yon,
    rakim_m: sayi(ham.Altitude),
    odometre_km: odo,
    adres: metin(ham.Address),
    bolge: metin(ham.Region),
    cekildi_at: cekildiAt,
  });

  gecmis.push({
    node: node,
    olcum_zamani: olcum,
    lat: lat,
    lon: lon,
    hiz_kmh: hiz,
    yon_derece: yon,
    odometre_km: odo,
  });
}

// List bos gelmesi hata DEGIL (tum cihazlar sessiz olabilir) - yazim atlanir.
// Ama satir gelip hicbiri kullanilabilir degilse bu bir bug'dir, gurultu cikar.
if (body.List.length > 0 && son.length === 0) {
  throw new Error(
    'Arvento ' + body.List.length + ' satir dondurdu ama hicbiri yazilabilir degil ' +
    '(koordinatsiz: ' + atlanan.koordinatsiz + ', tarihsiz: ' + atlanan.tarihsiz +
    ', nodesuz: ' + atlanan.nodesuz + ').'
  );
}

return [{
  json: {
    is_turu: 'konum',
    son: son,
    gecmis: gecmis,
    satir: son.length,
    ham_satir: body.List.length,
    atlanan: atlanan,
    cekildi_at: cekildiAt,
  },
}];

// =========================================================================
// PostgREST yazim sonucunu dogrula
// =========================================================================
// neverError:true kullandigimiz icin 4xx/5xx sessizce akiyor. Places
// workflow'undaki 2026-09-14 bug'i (PostgREST 401 govdesi hata sayilmadan
// gecti) tam olarak bu kontrolun eksikligiydi.
// =========================================================================

function kontrol(ad, res) {
  const st = res ? res.statusCode : undefined;
  if (typeof st !== 'number') {
    throw new Error(ad + ': yanit alinamadi - ' + JSON.stringify(res).slice(0, 300));
  }
  if (st < 200 || st >= 300) {
    const govde = typeof res.body === 'string' ? res.body : JSON.stringify(res.body || {});
    throw new Error(ad + ': PostgREST HTTP ' + st + ' - ' + govde.slice(0, 400));
  }
}

const norm = $('Dogrula ve Normalize').first().json;
kontrol('arac_konum_son upsert', $('Upsert Son Konum').first().json);
kontrol('arac_konum_gecmis insert', $('Insert Gecmis').first().json);

let oturum = '(bilinmiyor)';
try { oturum = $('Oturum Al').first().json.oturum_kaynagi; } catch (e) {}

return [{
  json: {
    is_turu: 'konum',
    durum: 'completed',
    yazilan_son: norm.satir,
    gecmis_aday: norm.gecmis.length,
    ham_satir: norm.ham_satir,
    atlanan: norm.atlanan,
    oturum_kaynagi: oturum,
  },
}];

// =========================================================================
// /v1/vehicle yanitini arvento_araclar satirlarina cevir
// =========================================================================
// PLAKA NORMALIZE ZORUNLU: 2026-09-14 testinde API tutarsiz dondu -
// 7 arac bitisik ("34PDV735"), 1 arac bosluklu ("34 PDV 736"). Orijinal
// plaka_ham'da saklanir.
//
// Payload'da BILEREK OLMAYAN iki alan:
//   arac_kod    -> elle yapilan rota araci eslemesi. PostgREST upsert yalniz
//                  govdedeki kolonlari UPDATE eder; buraya koymazsak her
//                  gunluk senkron elle yapilan eslemeyi EZMEZ.
//   ilk_gorulme -> insert'te default now(), update'te dokunulmaz.
//
// CompanyName / ChassisNumber okunmuyor: swagger'da tanimli ama API bu iki
// alani hic dondurmuyor (2026-09-14 testi).
// =========================================================================

function plakaNormalize(v) {
  return String(v == null ? '' : v).toUpperCase().replace(/[^0-9A-Z]/g, '');
}

function metin(v) {
  const s = String(v == null ? '' : v).trim();
  return s === '' ? null : s;
}

const items = $input.all();
if (items.length === 0) {
  throw new Error('Arac Listesi dugumunden hic item gelmedi.');
}

const res = items[0].json;
const status = res.statusCode;
const body = res.body !== undefined ? res.body : res;

if (status === 401) {
  throw new Error('Arvento oturumu gecersiz (401) - /v1/vehicle cagrisi reddedildi.');
}
if (typeof status === 'number' && (status < 200 || status >= 300)) {
  throw new Error('Arvento /v1/vehicle HTTP ' + status + ': ' + JSON.stringify(body).slice(0, 400));
}
if (!body || typeof body !== 'object') {
  throw new Error('Arvento /v1/vehicle govdesi nesne degil: ' + String(body).slice(0, 300));
}
if (body.HasError === true) {
  const msg = (body.Error && body.Error.Message) || body.Message || '(mesaj yok)';
  throw new Error('Arvento /v1/vehicle hata dondu - Status=' + body.Status + ', Message=' + msg);
}
if (!Array.isArray(body.List)) {
  throw new Error('Arvento /v1/vehicle yanitinda List dizisi yok: ' + JSON.stringify(body).slice(0, 400));
}
if (body.List.length === 0) {
  throw new Error('Arvento /v1/vehicle bos liste dondurdu - hesapta arac gorunmuyor.');
}

const gorulduAt = new Date().toISOString();
const rows = [];
const plakaSahibi = new Map();

for (const ham of body.List) {
  const node = metin(ham.Node);
  if (!node) continue;

  const plakaHam = metin(ham.LicensePlate);
  const plaka = plakaNormalize(plakaHam);
  if (!plaka) {
    throw new Error('Node ' + node + ' icin plaka bos geldi - arvento_araclar.plaka NOT NULL.');
  }
  if (plakaSahibi.has(plaka)) {
    throw new Error(
      'Ayni plaka iki node\'da: ' + plaka + ' -> ' + plakaSahibi.get(plaka) + ' ve ' + node +
      '. arvento_araclar.plaka UNIQUE oldugu icin yazim durduruldu.'
    );
  }
  plakaSahibi.set(plaka, node);

  rows.push({
    node: node,
    plaka: plaka,
    plaka_ham: plakaHam,
    surucu: metin(ham.Driver),
    arac_sinifi: metin(ham.VehicleClass),
    grup: metin(ham.NodeGroup),
    ekip: metin(ham.Crew),
    aktif: true,
    son_gorulme: gorulduAt,
  });
}

return [{ json: { is_turu: 'filo_bakim', rows: rows, satir: rows.length } }];

// =========================================================================
// Maintenance tarih pencereleri
// =========================================================================
// 2026-09-14 canli test: {"StartDate":"20250101000000","EndDate":"20261231000000"}
// (1,5 yil) -> Status 1012 "InvalidDateInterval". 3 aylik pencere kabul
// edildi (bos liste dondu - Arvento'da hic bakim kaydi girilmemis).
//
// Pencere araligi: gecmis 24 ay + gelecek 12 ay, 3'er aylik = 12 istek.
// Gelecek pencereler planlanmis bakimlar icin - Maintenance ucunun
// planlanmis kayit dondurup dondurmedigi DOGRULANMADI (kayit yok).
//
// Sinir gunleri konteyner saat dilimine gore hesaplaniyor; Maintenance
// filtresi gun hassasiyetinde oldugu icin birkac saatlik kayma onemsiz.
// =========================================================================

const GECMIS_AY = 24;
const GELECEK_AY = 12;
const ADIM_AY = 3;

function fmt(d) {
  const p = (n) => String(n).padStart(2, '0');
  return String(d.getFullYear()) + p(d.getMonth() + 1) + p(d.getDate()) +
         p(d.getHours()) + p(d.getMinutes()) + p(d.getSeconds());
}

const simdi = new Date();
const out = [];

for (let ay = -GECMIS_AY; ay < GELECEK_AY; ay += ADIM_AY) {
  const bas = new Date(simdi.getFullYear(), simdi.getMonth() + ay, 1, 0, 0, 0, 0);
  const bit = new Date(simdi.getFullYear(), simdi.getMonth() + ay + ADIM_AY, 1, 0, 0, 0, 0);
  out.push({ json: { StartDate: fmt(bas), EndDate: fmt(bit), pencere: fmt(bas) + '..' + fmt(bit) } });
}

return out;

// =========================================================================
// Maintenance pencerelerini birlestir + arac_bakim satirlarina cevir
// =========================================================================
// ⚠ BU KODUN PARSE VARSAYIMLARI DOGRULANMADI. 2026-09-14 itibariyla
// Arvento'da hic bakim kaydi yok, her sorgu List: [] donuyor. Su alanlarin
// gercek formati bilinmiyor:
//   - Km / PlannedKm / Amount string doner; ondalik ayirici virgul mu nokta
//     mi, Amount'ta "TL"/"₺" eki var mi?
//   - StartDate / EndDate / PlannedDate hangi formatta doner?
//   - RecordNo global unique mi?
// Bu yuzden her satirin TAMAMI ham_kayit jsonb kolonunda saklaniyor -
// parse yanlis cikarsa tablo veri kaybi olmadan yeniden uretilebilir.
//
// Istek/yanit alan adi tutarsizligi: ISTEKTE "LicencePlate" (c ile),
// YANITTA "LicensePlate" (s ile). Ikisi de okunuyor.
// =========================================================================

function plakaNormalize(v) {
  return String(v == null ? '' : v).toUpperCase().replace(/[^0-9A-Z]/g, '');
}

function metin(v) {
  const s = String(v == null ? '' : v).trim();
  return s === '' ? null : s;
}

// Ondalik ayirici belirsiz oldugu icin sezgisel: son ayiricidan sonra 1-2
// hane varsa o ondaliktir ("15,50" -> 15.5), 3 hane varsa binlik ayiricidir
// ("15.000" -> 15000).
function sayiCevir(v) {
  if (v === null || v === undefined) return null;
  let s = String(v).replace(/[^\d.,-]/g, '').trim();
  if (s === '' || s === '-') return null;
  const son = Math.max(s.lastIndexOf(','), s.lastIndexOf('.'));
  let birlesik;
  if (son === -1) {
    birlesik = s;
  } else {
    const kuyruk = s.length - son - 1;
    const tam = s.slice(0, son).replace(/[.,]/g, '');
    if (kuyruk >= 1 && kuyruk <= 2) {
      birlesik = tam + '.' + s.slice(son + 1);
    } else {
      birlesik = tam + s.slice(son + 1).replace(/[.,]/g, '');
    }
  }
  const n = Number(birlesik);
  return Number.isFinite(n) ? n : null;
}

function tarihCevir(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return null;
  let m = /^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})$/.exec(s);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = /^(\d{1,2})[./](\d{1,2})[./](\d{4})/.exec(s);
  if (m) return m[3] + '-' + String(m[2]).padStart(2, '0') + '-' + String(m[1]).padStart(2, '0');
  return null;
}

// Plaka -> node cozumu icin filo senkronunun ciktisi
const plakaNode = new Map();
try {
  const filo = $('Filo Normalize').first().json.rows || [];
  for (const r of filo) plakaNode.set(r.plaka, r.node);
} catch (e) { /* filo kolu calismadiysa node null kalir */ }

const items = $input.all();
const kayitlar = new Map();
const bosPencere = [];

// fullResponse:true HTTP ciktisini {statusCode, headers, body}'ye cevirdigi icin
// pencere etiketi yanitta TASINMIYOR - girdi item'lariyla index uzerinden
// eslestiriliyor (httpRequest her girdi icin sirayla bir cikti uretir).
let pencereler = [];
try { pencereler = $('Bakim Pencereleri').all().map((i) => i.json.pencere); } catch (e) {}

for (let i = 0; i < items.length; i += 1) {
  const it = items[i];
  const res = it.json;
  const pencere = pencereler[i] || '(pencere ' + (i + 1) + ')';
  const status = res.statusCode;
  const body = res.body !== undefined ? res.body : res;

  if (status === 401) {
    throw new Error('Arvento oturumu gecersiz (401) - Maintenance penceresi ' + pencere);
  }
  if (typeof status === 'number' && (status < 200 || status >= 300)) {
    throw new Error('Arvento Maintenance HTTP ' + status + ' (pencere ' + pencere + '): ' + JSON.stringify(body).slice(0, 300));
  }
  if (body && body.HasError === true) {
    const msg = (body.Error && body.Error.Message) || body.Message || '(mesaj yok)';
    throw new Error(
      'Arvento Maintenance hata dondu (pencere ' + pencere + ') - Status=' + body.Status + ', Message=' + msg +
      (body.Status === 1012 ? ' | InvalidDateInterval: pencere genisligi API sinirini asiyor, ADIM_AY kucultulmeli.' : '')
    );
  }
  if (!body || !Array.isArray(body.List)) {
    throw new Error('Arvento Maintenance yanitinda List dizisi yok (pencere ' + pencere + '): ' + JSON.stringify(body).slice(0, 300));
  }
  if (body.List.length === 0) { bosPencere.push(pencere); continue; }

  for (const ham of body.List) {
    const kayitNo = Number(ham.RecordNo);
    if (!Number.isFinite(kayitNo)) continue;

    const plakaHam = metin(ham.LicensePlate) || metin(ham.LicencePlate);
    const plaka = plakaNormalize(plakaHam) || null;

    kayitlar.set(kayitNo, {
      kayit_no: kayitNo,
      plaka: plaka,
      node: plaka && plakaNode.has(plaka) ? plakaNode.get(plaka) : null,
      tip: metin(ham.Type),
      firma: metin(ham.Firm),
      not_metni: metin(ham.Note),
      baslangic_tarihi: tarihCevir(ham.StartDate),
      bitis_tarihi: tarihCevir(ham.EndDate),
      planlanan_tarih: tarihCevir(ham.PlannedDate),
      km: sayiCevir(ham.Km),
      planlanan_km: sayiCevir(ham.PlannedKm),
      tutar: sayiCevir(ham.Amount),
      ham_kayit: ham,
      guncellendi: new Date().toISOString(),
    });
  }
}

const rows = Array.from(kayitlar.values());

return [{
  json: {
    is_turu: 'filo_bakim',
    rows: rows,
    satir: rows.length,
    pencere_sayisi: items.length,
    bos_pencere_sayisi: bosPencere.length,
  },
}];

// =========================================================================
// Filo/bakim kolunun tek sync_runs satirini hazirla
// =========================================================================
// BILEREK "running" satiri ACILMIYOR. Panorama'da her zincir once running
// satiri acip sonra completed'a cekiyor; hicbir error branch olmadigi icin
// zincir ortada coktugunde satir sonsuza kadar running kaliyor ve
// /api/sync/panorama/manual 409 dondurup "Simdi cek" butonunu kilitliyordu
// (bkz. sql/panorama_sync_stale_sweep.sql - o sorunu temizlemek icin ayri
// bir pg_cron isi yazilmak zorunda kalinmis).
//
// Burada tek satir EN SONDA, kesinlesmis durumla yaziliyor. Yetim "running"
// diye bir durum hic olusmuyor, dolayisiyla supurucu cron'a da gerek yok.
// Hata olursa Hata Kaydi kolu 'failed' satirini yaziyor.
// =========================================================================

// neverError:true yuzunden PostgREST 4xx/5xx sessizce akiyor - filo kolunun
// yazimlari burada acikca dogrulanir. (Konum kolunda ayni isi 'Konum Yazim
// Kontrol' yapiyor. Bu kontrol olmadan Places workflow'undaki 2026-09-14
// bug'inin aynisi olusur: PostgREST hata govdesi basari sayilip sync_runs'a
// 'completed' yazilir.)
function yazimKontrol(ad, dugum, zorunlu) {
  let res;
  try { res = $(dugum).first().json; }
  catch (e) {
    if (zorunlu) throw new Error(ad + ': dugum hic calismadi - ' + e.message);
    return;
  }
  const st = res ? res.statusCode : undefined;
  if (typeof st !== 'number') {
    throw new Error(ad + ': yanit alinamadi - ' + JSON.stringify(res).slice(0, 300));
  }
  if (st < 200 || st >= 300) {
    const govde = typeof res.body === 'string' ? res.body : JSON.stringify(res.body || {});
    throw new Error(ad + ': PostgREST HTTP ' + st + ' - ' + govde.slice(0, 400));
  }
}

yazimKontrol('arvento_araclar upsert', 'Upsert Arvento Araclar', true);
// Bakim upsert'i yalniz kayit varken calisir (Bakim Kaydi Var mi false dali).
yazimKontrol('arac_bakim upsert', 'Upsert Bakim', false);

function guvenliSayi(dugum, alan) {
  try {
    const v = $(dugum).first().json[alan];
    return Number.isFinite(Number(v)) ? Number(v) : 0;
  } catch (e) { return 0; }
}

const filoSatir = guvenliSayi('Filo Normalize', 'satir');
const bakimSatir = guvenliSayi('Bakim Normalize', 'satir');

return [{
  json: {
    rows: [{
      is_turu: 'filo_bakim',
      durum: 'completed',
      satir_sayisi: filoSatir + bakimSatir,
      hata: null,
      tamamlandi_at: new Date().toISOString(),
    }],
    filo_satir: filoSatir,
    bakim_satir: bakimSatir,
  },
}];

// =========================================================================
// Hata satirini hazirla - her iki kolun error cikislari buraya baglidir
// =========================================================================
// n8n onError:"continueErrorOutput" ile gelen item'da $json.error bulunur.
// Mesaj 2000 karaktere kirpiliyor: arvento_sync_runs.hata text ama
// devasa HTML hata sayfalari tabloyu kirletmesin.
// =========================================================================

const IZINLI = ['konum', 'filo_bakim'];

const items = $input.all();
const ilk = (items[0] && items[0].json) || {};
const hataObj = ilk.error || ilk;

let mesaj =
  (hataObj && (hataObj.message || hataObj.description || hataObj.reason)) ||
  JSON.stringify(hataObj);
mesaj = String(mesaj).slice(0, 2000);

let isTuru = ilk.is_turu;
if (!IZINLI.includes(isTuru)) {
  try { isTuru = $('Oturum Al').first().json.is_turu; } catch (e) { isTuru = null; }
}
if (!IZINLI.includes(isTuru)) isTuru = 'konum';

return [{
  json: {
    rows: [{
      is_turu: isTuru,
      durum: 'failed',
      satir_sayisi: null,
      hata: mesaj,
      tamamlandi_at: new Date().toISOString(),
    }],
    is_turu: isTuru,
    hata: mesaj,
  },
}];
